TP.register({id:"lp8-g2",lp:8,grade:"2",mode:"curriculum",checks:7,nextGrade:"3rd grade",build(E){const F=E.F;const CORNER_LOT="On the last Saturday of the month the whole block meets. They gather at the empty lot on the corner. Somebody brings a wheelbarrow. Somebody else brings a crate of seedlings in paper cups. We pull last year's dry stalks out of the beds. We shake the soil off the roots. Then we rake the beds flat. We cut shallow trenches with the edge of a hoe. The seedlings go in a hand's width apart. We press the soil around each one. By noon the field of weeds is gone. Instead the lot is four long green rows. Then it rains, which is exactly what we wanted.";const WHY_RAIN="Every day the sun warms the top of the ocean. Some of that water turns into a gas you cannot see. The gas rises with the warm air. High up, the air is cold, and the cold turns the gas back into tiny drops. Millions of those drops floating together are what you see as a cloud. The drops bump into each other and join up. A drop gets too heavy for the air to hold. Then it falls. That is rain. The same water has been going around like this for a very long time.";const TWO_ROWS="Ravi was given a packet of bean seeds. He planted them in two short rows. He watered both rows the same. But he could not stop wondering about the row by the fence. Every afternoon he dug one of those seeds up. He wanted to see how it was doing. He brushed the soil off and looked at it. Then he pushed it back in. After two weeks the first row was a line of green plants. They stood as high as his knee. The row by the fence was still bare soil. His aunt told him about seeds. A seed does its growing down in the dark. Every time he lifted it out, it had to start over. Ravi planted the fence row again. This time he kept his hands out of the soil. By the end of the month both rows were climbing their poles.";const POLLEN="A flower is a factory for making seeds, but it needs help to do the job. Deep inside the petals a flower keeps a drop of sweet nectar. A bee lands to drink it and brushes past the powdery yellow pollen on the way in. When that bee flies to the next flower of the same kind, some of the pollen rubs off. That is the step a flower cannot do on its own, and once it is done the flower can start building its seeds. The petals drop away, and what is left behind swells into a pod or a fruit with the seeds inside.";const WORDS=["bloomed","sprout","thirsty","sprinkle","growth","knee","raindrop","replant","quickly","should","drean","blork"];const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${text}</p>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>{const eye=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`;const blush=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`;const smile=(x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`;return eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4)});const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",SEEDC="#C9875A",STEM="#7FC08A",LEAF_A="#A8D49A",LEAF_INK="#4E7A46",SKY="#C8E9F8",GRASS="#CFE8A8",GRASS_D="#B2D986",GRASS_L1="#A3C777",GRASS_L2="#8EBB64",SOIL="#C08A5E",SOIL_D="#A8724E";function seedShape(x,y,s,c,noFace){return window.TP_SEEDIMG(x,y,s)}const seedSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*1.1)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a seed">${seedShape(w*.5,w*.626,w*.91,c)}</svg>`;const skyBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${SKY}" stroke="var(--line)" stroke-width="4"/>`;const plainBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const grassBand=(w,top,h)=>`<path d="M8 ${top} Q${w*.3} ${top-14} ${w*.56} ${top-2} T${w-8} ${top-6} V${top+h} H8 Z" fill="${GRASS}"/><path d="M8 ${top} Q${w*.3} ${top-14} ${w*.56} ${top-2} T${w-8} ${top-6}" fill="none" stroke="${GRASS_L1}" stroke-width="3.2" stroke-linecap="round"/><path d="M8 ${top+28} Q${w*.36} ${top+12} ${w*.64} ${top+26} T${w-8} ${top+22} V${top+h} H8 Z" fill="${GRASS_D}"/><path d="M8 ${top+28} Q${w*.36} ${top+12} ${w*.64} ${top+26} T${w-8} ${top+22}" fill="none" stroke="${GRASS_L2}" stroke-width="3.2" stroke-linecap="round"/>`;const soilRow=(x0,x1,top,h)=>`<rect x="${x0}" y="${top}" width="${x1-x0}" height="${h}" rx="12" fill="${SOIL}" stroke="${INK}" stroke-width="3"/><path d="M${x0+16} ${top+12} q22 -7 44 0 t44 0 t44 0 t44 0 t44 0" fill="none" stroke="${SOIL_D}" stroke-width="3" stroke-linecap="round" opacity=".8"/>`;function rowFig(n){const w=620,h=190,base=108;let b=skyBox(w,h)+grassBand(w,base,h-base-11);b+=soilRow(26,w-26,base+28,44);for(let i=0;i<n;i++)b+=seedShape(26+(i+.5)*(w-52)/n,base+50,44);return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A row of soil in the garden with ${n} seeds planted along it">${b}</svg>`}function pile(e,n,seed,label){const W=430,H=262;const pts=[];let x=seed,tries=0,gap=66;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};while(pts.length<n){const p=[44+rnd()*344,46+rnd()*150];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>gap))pts.push(p);if(++tries>6e3){tries=0;gap-=3}}let b=plainBox(W,H);pts.forEach(p=>{b+=e==="SEED"?seedShape(+p[0].toFixed(0),+p[1].toFixed(0),46):F.picXY(+p[0].toFixed(0),+p[1].toFixed(0),e,44)});b+=`<text x="${W/2}" y="${H-20}" font-size="24" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)" text-anchor="middle">${label}</text>`;return`<svg viewBox="0 0 ${W} ${H}" width="400" role="img" aria-label="${label}: a pile of ${n} pictures, not lined up">${b}</svg>`}const COL2={red:"#D9423A",blue:"#2F7FD9",green:"#3FA34D",yellow:"#F2C01E",purple:"#8E5BC9"};function regPoly(n,cx,cy,r){const p=[];for(let i=0;i<n;i++){const a=-Math.PI/2+i*2*Math.PI/n;p.push(`${n1(cx+r*Math.cos(a))},${n1(cy+r*Math.sin(a))}`)}return p.join(" ")}function shapeRowFig(){const st=`stroke="${INK}" stroke-width="2.6" stroke-linejoin="round"`,c=172,w=5*c+28,h=c+50;let b=plainBox(w,h);for(let i=0;i<5;i++){b+=`<rect x="${14+i*c}" y="12" width="${c-16}" height="${c-16}" rx="16" fill="var(--surface)" stroke="var(--line)" stroke-width="3"/>`;b+=`<text x="${14+i*c+(c-16)/2}" y="${h-16}" font-size="24" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)" text-anchor="middle">${i+1}</text>`}const g=(i,inner)=>`<g transform="translate(${14+i*c+16} 28) scale(1.24)">${inner}</g>`;b+=g(0,`<polygon points="50,8 93,88 7,88" fill="${COL2.red}" ${st}/>`);b+=g(1,`<polygon points="24,16 76,16 94,86 6,86" fill="${COL2.blue}" ${st}/>`);b+=g(2,`<polygon points="${regPoly(5,50,52,44)}" fill="${COL2.green}" ${st}/>`);b+=g(3,`<polygon points="${regPoly(6,50,52,44)}" fill="${COL2.purple}" ${st}/>`);b+=g(4,`<polygon points="18,34 36,16 92,16 74,34" fill="${COL2.yellow}" ${st}/><polygon points="74,34 92,16 92,72 74,90" fill="${COL2.yellow}" ${st} opacity=".72"/><rect x="18" y="34" width="56" height="56" fill="${COL2.yellow}" ${st}/>`);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,980)}" role="img" aria-label="Five numbered tiles. Tile 1 is a red triangle, tile 2 is a blue four sided figure, tile 3 is a green five sided figure, tile 4 is a purple six sided figure, and tile 5 is a yellow cube drawn as a solid box.">${b}</svg>`}const LOG=F.table(["Day","Sprouts counted","Weather"],[["Monday","12","rain"],["Tuesday","19","sun"],["Wednesday","26","sun"],["Thursday","31","clouds"]],{caption:"Garden Crew Log"});const STOPS=[{id:1,title:"Spring Word Flip",short:"Spring Words",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:95,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading words with vowel teams, blends, r-controlled vowels, two syllables, a prefix, a suffix, and an irregular spelling",key:["Read each word in order. drean and blork are made-up words: listen for the ea team sound and the or sound.","Watch for: the -ed ending said as /d/ (bloomed), the spr blend with the ou diphthong (sprout), r-controlled ir plus the y ending (thirsty), a three-letter blend with the -le ending (sprinkle), the ow team plus th (growth), silent k with ee (knee), a compound word (raindrop), the prefix re- (replant), the suffix -ly (quickly), an irregular spelling (should)."]}]},{id:2,title:"Fill the Trays",short:"Fill Trays",parts:[{std:["2.OA.A.1"],dur:140,dir:"Read each problem with your teacher. Solve it on your paper. You can draw or write a number sentence. Say your answer.",desc:"one-step addition and subtraction word problems within 100 with the unknown in different places",html:()=>`<div class="figure">${rowFig(6)}</div><p class="big" style="margin-top:0">The garden crew fills trays of seedlings and plants them out in long rows.</p>`,qs:["A tray has 48 cells. So far 29 of them are filled. How many cells are still empty?","The bean row got 36 seeds and the pea row got 27. How many seeds is that in all?","The bean row has 24 sprouts. The pea row has 19 more sprouts than the bean row. How many does the pea row have?","Some pots were on the cart. The crew carried out 38 of them. Now 17 are left on the cart. How many were on the cart at first?","There were 72 paper cups in the box. The crew used 46 of them. How many cups are left?"],key:["19 cells (29 + a box = 48, or 48 - 29 = 19)","63 seeds (36 + 27 = 63)","43 sprouts (24 + 19 = 43)","55 pots (a box take away 38 is 17, or 17 + 38 = 55)","26 cups (72 - 46 = 26)"]}]},{id:3,title:"The Corner Lot",short:"Corner Lot",parts:[{title:"Read the Story",std:["RF.2.4"],kind:"read",n:105,label:"words read correctly",dur:90,dir:"Read the story out loud. Use your best reading voice.",desc:"a 105-word grade-level story read aloud",html:()=>`<p class="passage g2-flu">${CORNER_LOT}</p>`,key:["105 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes.","Hard words to listen for: wheelbarrow, seedlings, trenches. A student who stops and sounds one out and gets it still counts it correct."]},{title:"Story Questions",std:["RL.2.1"],dur:80,dir:"Your teacher can read the story again if you need it. Then answer each question out loud.",desc:"asking and answering who, what, why, and how questions about key details in a story",html:()=>`<details class="look-back g2-story" open style="margin-bottom:10px"><summary>The Corner Lot (click to open or close the story)</summary><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${CORNER_LOT}</p></details>`,after:view=>{const d=view.querySelector("details.g2-story");if(d&&view.querySelector(".g2-flu"))d.open=false},qs:["Who meets at the empty lot?","When do they meet?","What do they pull out of the beds before they rake?","How far apart do the seedlings go?","Why is the writer glad about the rain at the end?","Your turn. Ask a question about the story. Start with who, what, where, when, why, or how."],key:["The whole block, everyone who lives there","The last Saturday of the month","Last year's dry stalks, and they shake the soil off the roots","A hand's width apart","The lot is full of brand new seedlings, and rain is just what new seedlings need. The story says it is exactly what they wanted.","Asks a question that is about this story and starts with a question word (for example: What does somebody bring in the crate? Where is the lot?)."]}]},{id:4,title:"Odd or Even Seeds",short:"Odd Even",parts:[{std:["2.OA.C.3"],n:3,dur:75,dir:"Count each pile. Say your answer out loud. Write the doubles on your paper and hold it up.",desc:"telling odd from even for a group of up to 20 and writing an even number as a sum of two equal addends",fig:()=>F.row(pile("SEED",14,19,"Pile A"),pile("drop",11,47,"Pile B")),qs:["Count Pile A. How many? Is it odd or even? Write it as a double.","Count Pile B. How many? Is it odd or even? How do you know?","Think about 18. Is it odd or even? Write it as a double."],key:["14 seeds. Even, because they pair up with none left over. 7 + 7 = 14","11 raindrops. Odd, because when you pair them up one is left over with no partner. Counting by 2s also lands on 10 and then one more.","Even. 9 + 9 = 18"]}]},{id:5,title:"Seedling Trays",short:"Arrays",parts:[{std:["2.OA.C.4"],n:2,dur:70,dir:"Look at the tray. Write your adding sentence on your paper and hold it up.",desc:"finding the total of a rectangular array and writing it as a sum of equal addends",html:()=>`<p class="big" style="margin-top:0">A seedling tray holds its sprouts in even rows.</p>`,fig:()=>`<div class="figure">${F.array(4,5,"sprout")}</div>`,qs:["How many sprouts are in the tray in all?","Write an adding sentence for the tray, using equal addends."],key:["20 sprouts","5 + 5 + 5 + 5 = 20 (one addend for each row), or 4 + 4 + 4 + 4 + 4 = 20 (one addend for each column). Either one counts."]}]},{id:6,title:"Why It Rains",short:"Why Rain",parts:[{std:["RI.2.1"],dur:80,dir:"Read about rain. Then answer each question out loud.",desc:"asking and answering what, where, why, and how questions about an informational text the student read",html:()=>passage("Why It Rains",WHY_RAIN),qs:["What does the sun do to the top of the ocean?","Where does the gas turn back into tiny drops?","What is a cloud made of?","Why does a drop finally fall?","Your turn. Ask a question about rain. Start with who, what, where, when, why, or how."],key:["It warms it, and some of the water turns into a gas you cannot see","High up, where the air is cold","Millions of tiny drops floating together","It joins up with other drops until it is too heavy for the air to hold","Asks a question that is about the topic and starts with a question word (for example: How long does a drop stay in a cloud? Why is the air colder high up?)."]}]},{id:7,title:"Fix the Garden Note",short:"Garden Note",parts:[{title:"Say It Right",std:["L.2.1"],dur:90,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular past tense, irregular plural, reflexive pronoun, adverb, word order, joining two sentences)",qs:["This summer the beans grow fast. Last summer they ____.","One leaf, two ____.","We carried the heavy flats all by ____.","Which word fits? The rain fell ____ on the roof. Is it soft or softly?","Mix-up! Put these words in order to make a sentence: <span class=mixrow><b class=mixw>the seedlings</b><b class=mixw>in the rain</b><b class=mixw>we planted</b></span>","Join these two sentences with the word <b>because</b>: We watered the row. The soil was dry."],key:["grew","leaf","ourselves","softly","We planted the seedlings in the rain.","We watered the row because the soil was dry."]},{title:"Write It Right",std:["L.2.2"],dur:90,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters in place names, an apostrophe for a possessive and a contraction, a comma in a letter greeting, spelling two patterns)",qs:["Fix this sentence: <b>we walked down maple street to the river garden</b>","The trowel belongs to the class. Write the missing word: <b>the ____ trowel</b>","This is the start of a letter. Write it and add the missing mark: <b>Dear Nel</b>","Write <b>do not</b> as one short word with an apostrophe.","Listen. Write the word your teacher says.","Listen. Write the second word your teacher says."],key:["We walked down Maple Street to the River Garden. (capital W to start, capital M and capital S in the street name, capital R and capital G in the garden name, and a period)","class’s (apostrophe before the s)","Dear Nel, (comma after Nel)","don’t (apostrophe where the o of not comes out)","Say: “Sprout. One green sprout came up in the row.” The student writes sprout (the spr blend and the ou team).","Say: “Garden. The garden is full of rain.” The student writes garden (two syllables, r-controlled ar)."]}]},{id:8,title:"Greenhouse Math",short:"Greenhouse",parts:[{std:["2.NBT.B.7"],dur:150,dir:"Solve each one on your paper. Show your work and hold it up. Say your answer.",desc:"adding and subtracting within 1000 with a place value strategy and relating it to a written method",html:()=>`<p class="big" style="margin-top:0">The greenhouse keeps a count of every seedling it starts.</p>`,qs:["The greenhouse started 348 bean seedlings and 276 pea seedlings. How many is that in all? Show how you added.","The crew wants 500 seedlings ready by May. So far 237 are ready. How many more are needed?","They started 467 seedlings in March and 185 more in April. How many did they start in all?","There were 803 empty pots on the shelf. The crew filled 426 of them. How many empty pots are left?"],key:["624 seedlings (348 + 276 = 624). Listen for hundreds with hundreds, tens with tens, ones with ones, and for making a new ten and a new hundred.","263 more (500 - 237 = 263). This one needs two decomposes, so watch the work.","652 seedlings (467 + 185 = 652). A new ten and a new hundred are both made here.","377 pots (803 - 426 = 377). Two decomposes again, and the 0 in the tens place is the tricky part."]}]},{id:9,title:"The Seed Shop",short:"Seed Shop",parts:[{std:["2.MD.C.8"],n:4,dur:110,dir:"Look at the coins. Write each answer on your paper and hold it up.",desc:"money word problems with quarters, dimes, nickels, pennies, and dollars, using the cent sign and the dollar sign",html:()=>`<p class="big" style="margin-top:0">The seed shop opens the first week of spring.</p>`,fig:()=>F.coins(["Q","Q","D","N","P","P"]),qs:["Nel has these coins in her pocket. How much money does she have? Write it with the right symbol.","A packet of bean seeds costs 45¢. Nel buys one. How much money does she have left?","Ravi has 3 dimes and 4 pennies. Write how much money he has.","A trowel costs $3 and a seed packet costs $2. Write how much they cost together."],key:["67¢ (25 + 25 + 10 + 5 + 1 + 1 = 67). $0.67 is also correct, but 67¢ is the grade 2 target.","22¢ (67 - 45 = 22)","34¢ (30 + 4 = 34)","$5 (3 + 2 = 5). The dollar sign goes in front of the number."]}]},{id:10,title:"Garden Graph",short:"Graph",parts:[{std:["2.MD.D.10"],n:5,dur:110,dir:"Look at the graph. Say the first four answers out loud. Draw the last one on your paper and hold it up.",desc:"reading a bar graph with four categories and a single-unit scale, solving compare and put-together problems from it, and drawing a new bar",html:()=>`<p class="big" style="margin-top:0">The crew counted the sprouts in each row and made this graph. The numbers up the side go up by one.</p>`,fig:()=>F.row(F.barGraph({title:"Sprouts up in each row",cats:["Beans","Peas","Corn","Kale"],vals:[8,5,9,6],max:10,step:1})),qs:["How many sprouts are up in the corn row?","Which row has the fewest sprouts, and how many?","How many more corn sprouts are there than pea sprouts?","How many sprouts are in the bean row and the kale row together?","A fifth row, Carrots, has 7 sprouts. Draw that bar on your paper. How high does it reach, and where does its top sit compared to the other bars?"],key:["9 sprouts","Peas, with 5","4 more (9 - 5 = 4)","14 sprouts (8 + 6 = 14)","Up to the 7 line. Its top sits above the kale bar, which is at 6, and below the bean bar, which is at 8."]}]},{id:11,title:"Two Rows at Once",short:"Two Steps",parts:[{std:["2.OA.A.1"],dur:100,dir:"Each problem takes two steps. Solve it on your paper and say your answer.",desc:"two-step addition and subtraction word problems within 100",html:()=>`<p class="big" style="margin-top:0">On planting day the crew works two rows at a time, so most counts take two steps.</p>`,qs:["The shed had 64 seed packets. 18 went to one class and 23 went to another. How many packets are left in the shed?","One flat holds 9 pots and a second flat holds 7 pots. The crew plants 5 of those pots out in the garden. How many pots are still in the flats?","Spot the mistake. There were 80 paper cups. The crew used 26 in the morning, and then brought 15 more cups out from the shed. A helper wrote 80 - 26 - 15 = 39. What did the helper do wrong? Fix it."],key:["23 packets (18 + 23 = 41, then 64 - 41 = 23)","11 pots (9 + 7 = 16, then 16 - 5 = 11)","The helper took the 15 new cups away instead of adding them on. 80 - 26 = 54, then 54 + 15 = 69 cups."]}]},{id:12,title:"The Two Rows",short:"Two Rows",parts:[{std:["RL.2.2"],n:4,dur:120,dir:"Read the story out loud. Then answer each question out loud.",desc:"recounting a story in order and telling its lesson",html:()=>passage("The Two Rows",TWO_ROWS),qs:["Tell me this story again in your own words. What happened first, next, and last?","What did Ravi do every afternoon?","Why did the row by the fence fall behind?","What is the lesson of this story? Say it in one sentence."],key:["Recounts the main events in order: Ravi planted two rows and watered them the same, every afternoon he dug a seed up out of the fence row to look at it, after two weeks one row was knee high and the fence row was still bare, his aunt told him a seed grows down in the dark, and he planted the fence row again and left it alone until both rows were climbing. Count it correct when the big events are there in the right order.","He dug a seed up out of the fence row, brushed it off, looked at it, and pushed it back in","Because he kept lifting that seed back out, so it had to start its growing over every single time","Any wording of: growing things need time, and you have to leave them alone to do it. Checking on something over and over can stop it from working. Count it correct when the lesson is about the whole story, not just one detail."]}]},{id:13,title:"Workshop Report",short:"Report",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:65,read:POLLEN,dir:"Listen first. Then answer your teacher's questions out loud.",desc:"recounting and describing key ideas and details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ic("ear",96)} ${ic("bee",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read a report about flowers and bees.</p>`,key:["Ask: What does a bee come to the flower for? (a drop of sweet nectar, deep inside the petals)","Ask: Describe how the pollen gets from one flower to another. (the bee brushes past the powdery yellow pollen going in, and some of it rubs off on the next flower of the same kind)","Ask: What is the one step a flower cannot do on its own? (moving its pollen to another flower)","Say: Tell me two more things you learned. (any two: a flower is a factory for making seeds, the pollen is powdery and yellow, the petals drop away afterward, what is left swells into a pod or a fruit, the seeds are inside it)"]},{title:"Tell Me About It",std:["SL.2.4"],n:4,label:"checks met",dur:50,dir:"Tell about it out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with facts and details, in clear complete sentences",html:()=>`<p class="big">Tell me about a time you planted something, or a time you got caught out in the rain. Where were you? What did you do? What did you see or hear?</p>${pills("First","Next","Last")}`,key:["Tells what happened in an order that makes sense","Gives facts that fit (where, when, who, or what)","Uses describing details (how it looked, felt, or sounded)","Speaks in complete sentences, loud and clear enough to hear"]}]},{id:14,title:"The Garden Log",short:"Garden Log",parts:[{std:["W.2.8"],dur:85,dir:"Use the log to answer. Say the first two answers out loud. Write number 3 on your paper and hold it up. Then say number 4.",desc:"gathering information from a provided log and recalling information from experience to answer questions",html:()=>`<p class="big" style="margin-top:0">The garden crew writes down how many new sprouts came up each day, and what the weather was like.</p>`,fig:()=>F.row([seedSvg(68),"One seed"],LOG),qs:["Use the log. Which day had the most new sprouts?","Which days were sunny?","A friend asks, “Did more sprouts come up on Monday or on Wednesday?” Write one sentence that answers your friend. Use the log.","Now use what you remember. Think of a time you helped take care of a plant or an animal. What did you have to do for it?"],key:["Thursday, with 31 sprouts","Tuesday and Wednesday","The sentence says Wednesday and uses the numbers from the log (Wednesday had 26 and Monday had 12).","Tells one thing remembered from a real experience, in a sentence that answers the question (for example: I filled the water bowl for our dog every morning.)."]}]},{id:15,title:"Spring Writing",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"The Better Job",icon:"💬",hint:"Pick one and give your reasons"},std:["W.2.1"],n:5,label:"checks met",dur:150,dir:WRITE_DIR,desc:"an opinion piece about the better job on garden day, with reasons, linking words, and a closing",html:()=>`<p class="big">On garden day there are two jobs: digging the beds, or filling the watering cans and watering the rows. Which job is the better one? Write what you think. Give two reasons. Use the word <b>because</b> or <b>also</b>. End with one last sentence.</p>${pills("I think","because","also","So")}`,key:["Introduces the topic: which garden day job is better (W.2.1)","States a clear opinion, naming one of the two jobs (W.2.1)","Supplies at least two reasons that support the opinion (W.2.1)","Uses a linking word such as because, and, or also to connect the opinion to a reason (W.2.1)","Ends with a concluding sentence (W.2.1)"]},{alt:{group:"write",key:"facts",label:"Seed to Plant",icon:"📖",hint:"Explain it with facts"},std:["W.2.2"],n:4,label:"checks met",dur:150,dir:WRITE_DIR,desc:"an informative piece explaining how a seed turns into a plant, with facts, a definition, and a closing",html:()=>`<p class="big">Explain how a seed turns into a plant. Start by telling the reader what your writing is about. Use facts. Somewhere in it, tell the reader what the word <b>sprout</b> means. End with one last sentence that wraps it up.</p>${pills("This is about","A sprout is","First","Then","So")}`,key:["Introduces the topic in the first sentence, so the reader knows what the writing is about (W.2.2)","Uses facts to develop the points, such as: a seed needs water, a root goes down first, leaves catch the sunlight (W.2.2)","Includes a definition: tells the reader what a sprout is (W.2.2)","Ends with a concluding statement (W.2.2)"]},{alt:{group:"write",key:"story",label:"The Last Row",icon:"✏",hint:"Tell what happened, in order"},std:["W.2.3"],n:4,label:"checks met",dur:150,dir:WRITE_DIR,desc:"a short narrative with events in order, details about actions and feelings, time words, and an ending",html:()=>`<p class="big">You are on the garden crew. You have one row left to plant, and the first fat raindrops start to fall. Write a story about what happens next. Tell it in order. Tell what you did and how you felt. Write 4 sentences.</p>${pills("First","Then","After that","In the end")}`,key:["Tells about one event or a short set of events in order (W.2.3)","Includes details about actions, thoughts, or feelings (W.2.3)","Uses time words like first, then, after that, or in the end (W.2.3)","Ends with a sentence that wraps up the story (W.2.3)"]}]},{id:16,title:"Read the Rows",short:"Read Rows",parts:[{std:["RF.2.3"],n:3,dur:55,dir:"Read each line out loud. Sound out any word that is tricky.",desc:"applying grade-level phonics and word-analysis skills to decode words in text",html:()=>`<ol class="qlist" style="font-size:1.6rem;line-height:1.9"><li>The bright green shoots pushed through the crumbly brown soil.</li><li>We unpacked eight flats and replanted every seedling.</li><li>A light rain sprinkled the thirsty rows all afternoon.</li></ol>`,key:["Line 1: listen for igh in bright, the ee team in green, the oo team in shoots, ough in through, and the -ly ending in crumbly.","Line 2: listen for the prefix un in unpacked, the -ed ending said as /t/ in unpacked, the irregular eigh in eight, and the prefix re in replanted.","Line 3: listen for igh in light, the ai team in rain, the three-letter blend spr with the -le ending in sprinkled, r-controlled ir in thirsty, and the two syllables in afternoon."]}]},{id:17,title:"The Seedling Count",short:"Places",parts:[{std:["2.NBT.A.1","2.NBT.A.3"],n:3,dur:65,dir:"Look at the blocks. Say the first two answers out loud. Write the last one on your paper.",desc:"reading hundreds, tens and ones off a block model, and writing a number in numerals, words and expanded form",html:()=>`<p class="big" style="margin-top:0">The greenhouse counted this spring's seedlings with blocks. A flat is a hundred, a stick is a ten, and a cube is a one.</p>`,fig:()=>F.row(matSvg(4,0,6)),qs:["How many hundreds, how many tens, and how many ones are on the mat? What number is that?","In that number, what does the 4 stand for? How many tens would it take to make that same amount?","Write that number three ways on your paper: in numerals, in words, and in expanded form."],key:["4 hundreds, 0 tens, and 6 ones. The number is 406 (2.NBT.A.1). The empty tens place is the part to listen for: a student who says 46 read the mat as two piles instead of three places","The 4 stands for 4 hundreds, which is 400. It takes 40 tens to make 400, because 10 tens make one hundred (2.NBT.A.1)","406, four hundred six, and 400 + 6 (2.NBT.A.3). Expanded form leaves the empty tens place out. Writing 400 + 0 + 6 is fine too. Watch for four hundred and six, which is the spoken habit, not the written form"]}]},{id:18,title:"Count the Rows",short:"Skip Count",parts:[{std:["2.NBT.A.2"],n:3,dur:50,dir:"Count out loud. Your teacher will tell you where to start and where to stop.",desc:"counting on within 1000 and skip counting by 5s, 100s and 2s",html:()=>`<p class="big" style="margin-top:0">The crew counts the whole lot out loud while they plant.</p><div class="figure">${ic("sprout",96)}</div>`,qs:["Start at 596 and count on to 605.","Skip count by 5s, starting at 60 and stopping at 100.","Skip count by 100s from 150 to 650. Then skip count by 2s from 24 to 36."],key:["596, 597, 598, 599, 600, 601, 602, 603, 604, 605. Crossing 599 to 600 is the part that trips students up","60, 65, 70, 75, 80, 85, 90, 95, 100","150, 250, 350, 450, 550, 650. Then 24, 26, 28, 30, 32, 34, 36. Note which of the two was harder"]}]},{id:19,title:"Measure the Seedling",short:"Measure",parts:[{std:["2.MD.A.1"],n:4,dur:85,dir:"Look at the seedling lined up on the ruler. Answer out loud. For the last one, get a real ruler and measure.",mats:["a ruler"],desc:"reading a length off a ruler, knowing why a measure starts at zero, choosing the right tool for a long object, and measuring a real object with a ruler",html:()=>`<p class="big" style="margin-top:0">The ruler is marked in inches. The gold bar is the seedling, laid along it.</p>`,fig:()=>F.row(F.ruler({length:12,px:52,item:7,itemLabel:"seedling"})),qs:["How long is the seedling, and in what unit?","Why does the end of the seedling have to line up with the 0 and not with the 1?","Now you have to measure the whole garden bed, which is about 20 feet long. Would you pick this 12 inch ruler or a measuring tape? Why?","Now get a real ruler. Pick up a leaf, a pencil, or a spoon and measure it. How long is it?"],key:["7 inches. The bar starts at 0 and ends at 7","Because the measure counts the units the object actually covers. Starting at the 1 would leave out the first inch and the answer would come out one short","The measuring tape. The bed is far longer than the ruler, so the ruler would have to be picked up and moved many times, and every move is a chance to lose the place. Saying a yardstick or a tape both count","Picks up the ruler, lines one end of the object up with the 0, reads the nearest whole inch or centimeter, and says the unit"]}]},{id:20,title:"Garden Day Clock",short:"Clocks",parts:[{std:["2.MD.C.7"],n:3,dur:55,dir:"Look at the two clocks. Answer out loud.",desc:"telling time to the nearest five minutes with a.m. and p.m., and knowing time relationships",fig:()=>F.row(F.label(F.clock(7,15),"Clock A: the crew arrives"),F.label(F.clock(3,50),"Clock B: the crew packs up")),qs:["What time does Clock A show? The crew arrives in the morning, so say it with a.m. or p.m.","What time does Clock B show? The crew packs up in the afternoon.","How many minutes are in one hour? How many weeks are in one year?"],key:["7:15 a.m. The long hand is on the 3, which is 15 minutes past","3:50 p.m. The long hand is on the 10, which is 50 minutes past. The short hand sits very close to the 4, so watch for 4:50","60 minutes in an hour. 52 weeks in a year"]}]},{id:21,title:"Shapes in the Garden",short:"Shapes",parts:[{std:["2.G.A.1"],n:3,dur:55,dir:"Look at the five tiles. Say the first two answers out loud. Draw the last one on your paper.",desc:"naming shapes by their number of sides and angles, identifying a cube, and drawing a shape to a given attribute",fig:()=>F.row(shapeRowFig()),qs:["Name tiles 1, 2, 3 and 4. For each one, say how many sides it has.","Which tile is a cube? How can you tell?","On your paper, draw a closed shape with 5 sides and 5 angles. What is it called?"],key:["1 is a triangle with 3 sides. 2 is a quadrilateral with 4 sides. 3 is a pentagon with 5 sides. 4 is a hexagon with 6 sides. Calling tile 2 a trapezoid is right too, and a trapezoid is one kind of quadrilateral","Tile 5. It is solid, not flat, and it is built from 6 square faces that are all the same size","Any closed figure with 5 straight sides and 5 angles. It is called a pentagon. It does not have to be regular or neat, but the sides have to join up with no gaps"]}]},{id:22,title:"Three Trays of Radish Seed",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">Three trays of radish seeds were sown on the corner lot on the same spring morning, 30 seeds in each tray.</p>
     <table class="bigTable"><tr><th>Tray</th><th>What it got</th><th>After twelve days</th></tr>
     <tr><td>1</td><td>out in the open, rain and sun</td><td>27 seedlings, short and dark green</td></tr>
     <tr><td>2</td><td>under a plank, rain could not reach it</td><td>4 seedlings, then they dried out</td></tr>
     <tr><td>3</td><td>out in the open, but covered by an upturned pail</td><td>22 seedlings, long, pale and bent over</td></tr></table>
     <div class="figure">${ic("sprout",88)}${ic("rain",88)}</div>`,qs:["Which tray did best, and what did it get?","Tray 2 and tray 3 each went wrong, but for different reasons. Say what each one was missing.","You want to test only whether radishes need sunlight. Name two things you would keep the same, and name the one thing you would change."],key:["Tray 1, 27 short dark green seedlings. It got both sunlight and water.","Tray 2 was missing water, because the plank kept the rain off. Tray 3 was missing sunlight, because the pail kept the light off. Both have to be named for full credit.","Keep the same: the same seeds, the same number of seeds, the same soil, the same watering. Change only one thing: one tray open to the sun and one tray covered from the light but still watered. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it moves seeds",html:()=>`<p class="big">Ants on the lot pick up small seeds. They carry them down into their tunnels. They leave some behind in the soil. Those seeds grow in spring.</p>
     <div class="figure">${ic("sprout",88)}${ic("herb",88)}</div>
     <p class="big">Draw a model you could really build out of things from a kitchen drawer, such as a clothes peg or a bent paper clip, that would pick one small seed up off the path and put it down under the soil.</p>`,qs:["Draw your model. Label the part that grips the seed and the part that gets it under the soil.","Which animal job does your model copy, and why does getting the seed under the soil help the plant?"],key:["Any model with a gripping part and a digging or pushing part: a peg, a bent paper clip, tweezers and a small spoon, a straw with a plunger. The two labeled parts are what to look for.","It copies an ant carrying seeds down into its tunnels. Under the soil the seed is damp and safe from birds, so it can sprout, while a seed left on a hard path dries out or gets eaten."]}]},{id:23,title:"The Wet Ditch and the Gravel Strip",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">Two children spent twenty minutes in each of two places on the lot and wrote down every kind of living thing they could find.</p>
     <table class="bigTable"><tr><th>The wet ditch at the back</th><th>The dry gravel strip by the fence</th></tr>
     <tr><td>4 kinds of rush and tall weed</td><td>2 kinds of low flat weed</td></tr>
     <tr><td>2 kinds of worm</td><td>1 kind of ant</td></tr>
     <tr><td>1 frog, 1 kind of water snail</td><td>1 kind of beetle</td></tr>
     <tr><td>3 kinds of fly or midge</td><td></td></tr></table>
     <div class="figure">${ic("frog",80)}${ic("leaf",80)}</div>`,qs:["How many kinds of living things are on the wet ditch list?","Name one living thing from the ditch that would not last long in the gravel strip, and say why.","The two places are ten paces apart on the same lot. Why are the lists so different?"],key:["11. Four rushes and weeds, two worms, one frog, one water snail and three flies or midges.","Any sensible pick with a reason: a worm would dry out in the gravel because it needs damp soil, a frog needs water to keep its skin wet, a water snail needs water to live in.","Because one place is wet with soft soil and the other is dry stony ground in the sun, and living things live where they can get what they need. Ten paces is enough to change everything if the water and soil change."]}]},{id:24,title:"One Day, or Twenty Years",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about this corner of the city, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>a city street repair report</td><td>In one day of heavy spring rain, water carried gravel right across the lot and piled it against the fence.</td></tr>
     <tr><td>a photograph from twenty years ago, next to one from today</td><td>The clay bank at the back of the lot has worn back about the width of a doorway since the first photograph was taken.</td></tr></table>`,qs:["Which note tells about a change that happened in one day?","Which note tells about a change that took twenty years?","Name one more change to the land that happens quickly, and one that happens slowly."],key:["The street repair report, the gravel carried across the lot in one day of rain.","The pair of photographs, the clay bank worn back the width of a doorway over twenty years.","Quick: a flood, a rockfall, a bank falling in, a tree pushed over in a storm. Slow: a stream cutting a valley, a cliff wearing back, soil building up year by year. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">In spring the water on this lot is easy to find.</p>
     <div class="figure">${ic("drop",80)}${ic("rain",80)}${ic("snowflake",80)}</div>`,qs:["Name three places on or near this lot where you would find water.","Most of the water on Earth is in the ocean and it is salty. Name a place nearby where the water is fresh instead.","Hail fell on the lot last week. Is hail solid or liquid? Is the water in the puddles solid or liquid?"],key:["Any three: the puddles, the rain barrel, the ditch, the creek two streets away, the tap, clouds, in the soil, inside the plants.","The creek, the ditch, the rain barrel, a pond, or the tap. Fresh water is the kind plants can be watered with.","Hail is solid. The water in the puddles is liquid."]}]},{id:25,title:"Holding the Beds, and a Map of the Block",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things put in place to stop water from washing the soil away",html:()=>`<p class="big">Spring rain washes soil off the new beds, which sit on a gentle slope. Two ways of holding it were tried and the soil caught in a tray at the bottom was weighed.</p>
     <table class="bigTable"><tr><th>What was on the beds</th><th>Soil caught after a month of rain</th></tr>
     <tr><td>bare soil</td><td>6 kilograms</td></tr>
     <tr><td>a layer of straw over the soil</td><td>1 kilogram</td></tr>
     <tr><td>a board set along the low edge of each bed</td><td>2 kilograms</td></tr></table>`,qs:["Which one kept the most soil on the beds?","How do you know, using the numbers in the chart?","The boards also keep the soil off the path. Why might the club use both the straw and the boards?"],key:["the layer of straw over the soil","Only 1 kilogram washed off under the straw, 2 kilograms washed off with the boards, and 6 kilograms washed off the bare soil. The reason must come from the numbers.","Because they do two different jobs. The straw stops the rain hitting the soil and loosening it, and the board catches whatever still moves before it reaches the path. Any answer about the two working together counts."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the block. Put in the slope the lot sits on, the flat ground by the gate, the creek two streets over, and the pond in the park. Add a key that says which is which.</p>
     <div class="figure">${ic("map",88)}${ic("mountain",88)}${ic("tulip",88)}</div>`,qs:["Draw your model map with the slope, the flat ground, the creek and the pond on it.","Show me your key. Which parts are land and which parts are water?","Is the creek a flowing body of water or a still one? Name a still one and a flowing one."],key:["All four on the page and told apart by shape or color: the slope as a bump or as rings, the flat ground left flat, the creek as a line, the pond as a closed shape.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","A creek flows. Still: a pond, a lake, a puddle. Flowing: a creek, a stream, a river."]}]},{id:26,title:"Sorting the Seed Shop Shelf",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">Four things off the seed shop shelf, and what was noticed about each one.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What was noticed</th></tr>
     <tr><td>a seed packet</td><td>paper</td><td>thin, bends easily, soaks water up, tears easily</td></tr>
     <tr><td>a seedling tray</td><td>plastic</td><td>stiff but bends a little, keeps water in, light</td></tr>
     <tr><td>a plant label</td><td>wood</td><td>hard, rough, floats, soaks water up</td></tr>
     <tr><td>a ball of twine</td><td>cotton</td><td>soft, bends easily, fluffy</td></tr></table>`,qs:["Sort the four items into a group that soaks water up and a group that does not.","Which two bend easily, and which one is hard?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Soaks water up: the paper packet, the wooden label and the cotton twine. Does not: the plastic tray.","Bend easily: the paper packet and the cotton twine. Hard: the wooden label. The plastic tray is stiff and bends only a little, so either group can be argued for it as long as the student says why.","Any property that can be seen or felt and that really splits the four: tears easily or does not, rough or smooth, floats or sinks, light or heavy. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The club needs little covers to put over young seedlings on cold spring nights. Three materials were tried over three nights and the trays were checked each morning.</p>
     <table class="bigTable"><tr><th>Cover</th><th>Seedlings still standing in the morning</th><th>Light that got through in the day</th></tr>
     <tr><td>no cover</td><td>12 of 24</td><td>all of it</td></tr>
     <tr><td>a cardboard box</td><td>24 of 24</td><td>none</td></tr>
     <tr><td>a clear plastic cloche</td><td>23 of 24</td><td>nearly all of it</td></tr></table>`,qs:["Which cover should the club use?","Which two pieces of the chart make you sure?","The cardboard box saved every single seedling. Why is it still the wrong choice?"],key:["the clear plastic cloche","Nearly every seedling was still standing, 23 of 24, and nearly all the light still got through. Both columns have to be used, not just one.","No light got through it. The seedlings would be saved from the cold and then starve in the dark, so somebody would have to lift the box off every morning and put it back every night."]}]},{id:27,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">The tray stand is on the lot. It is made of 6 bricks and 3 boards. They are just stacked. Nothing is holding it. The club took it down. They wanted to move it. A sunnier spot was better.</p>
     <div class="figure">${ic("board",88)}${ic("box",88)}</div>`,qs:["The stand is gone. Are the bricks and boards gone too? What is lying on the ground?","Build something new in your head out of those 6 bricks and 3 boards. What is it, and how do the pieces go together?"],key:["No. All 6 bricks and all 3 boards are still there. They are the same pieces, just not stacked as a stand any more.","Any real thing from 6 bricks and 3 boards: a step, a bench, a path edge, a low wall, a cold frame, a ramp for a wheelbarrow. Listen for how the pieces sit on each other, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened in the kitchen next to the lot on the same morning.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A knob of butter was put in a warm pan and spread out into a thin yellow liquid.</td></tr>
     <tr><td>An egg was cracked into the same warm pan and the clear part turned white and firm.</td></tr></table>
     <div class="figure">${ic("pan",80)}${ic("egg",80)}</div>`,qs:["Put the pan of melted butter in the refrigerator. What happens to it?","Put the cooked egg in the refrigerator. Does the white part go clear and runny again?","Which of the two changes can be undone, and what is your evidence?"],key:["It goes hard again and is butter, in the shape of the pan.","No. It stays white and firm. Cold does not turn it back into the clear runny part.","The butter change can be undone. The evidence is that the butter goes hard again when it is cooled and melts again when it is warmed, while the cooked egg white never goes back to clear and runny. Listen for the student using what happened, not just saying yes or no."]}]},{id:28,title:"The Trays That Blow Off",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The seedling trays sit on a long shelf. The shelf is against the fence. So they catch the morning sun. Spring wind comes along the fence line. It lifts the light plastic trays. It tips them onto the gravel. Soil goes everywhere. The seedlings have to be potted up again.</p>`,qs:["What is the problem the club wants to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The wind lifts the light trays off the shelf and tips them onto the gravel. Naming the trays blowing off, not the repotting, is the problem.","Any real question: how light is a full tray, how wide is the shelf, which way does the wind come along the fence, how many trays are there, is there a lip on the shelf. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would keep the trays on the shelf in a spring wind. Still let the sun reach them. Think hard about its shape.</p>
     <div class="figure">${ic("board",88)}${ic("sprout",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew keeps the trays down without shading them."],key:["Any design that could really hold a tray and still let light in: a lip or rail along the shelf front, slots in the shelf that each tray drops into, a wire frame over the tops, clips at the tray corners, a low screen on the windy side only.","The shape is the part being checked, and so is the light. Something like: the lip stops it sliding off but is below the leaves, the slots hold the bottom so the top is still open to the sun, the wire frame holds them down and the sun goes straight through it."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">Both fixes were used for two weeks with 12 trays each.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Trays tipped over</th><th>Seedlings lost</th></tr>
     <tr><td>slots in the shelf for each tray</td><td>0</td><td>0</td></tr>
     <tr><td>a rail along the shelf front</td><td>3</td><td>26</td></tr></table>`,qs:["Which fix worked better?","How do you know? Use both columns."],key:["the slots in the shelf for each tray","No trays tipped and no seedlings were lost with the slots, while 3 trays tipped and 26 seedlings were lost with the rail. Both columns have to be used, not just the tipping."]}]},{id:29,title:"This Corner Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the sign the club put up by the gate.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>Long ago this corner was a pasture, and horses from the next street grazed here.</td></tr>
     <tr><td>2</td><td>Yesterday the club sowed radishes in four beds.</td></tr>
     <tr><td>3</td><td>Before there were shops on this street, people here grew most of their own food in gardens like this one.</td></tr>
     <tr><td>4</td><td>This morning a city truck brought a load of compost to the gate.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Pick one of the long ago lines and say what is different about this corner now."],key:["Lines 1 and 3, the horse pasture and people growing most of their own food.","Lines 2 and 4, sowing the radishes yesterday and the compost truck this morning.","Either one: the pasture is now a garden with beds and a fence instead of grass and horses; most food is bought in shops now, and a garden like this one grows only some of it."]}]},{id:30,title:"Where Things Are on the Block",short:"Block Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The block around the lot, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("books",46)} library</td><td>${ic("tree",46)} park</td><td>${ic("drop",46)} park pond</td></tr>
     <tr><th>B</th><td>${ic("bus",46)} bus stop</td><td>${ic("tulip",46)} corner lot</td><td>${ic("bread",46)} bakery</td></tr>
     <tr><th>C</th><td>${ic("truck",46)} loading lane</td><td>${ic("sprout",46)} seed beds</td><td>${ic("wateringCan",46)} rain barrels</td></tr></table>
     <p class="big">${ic("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>
     <p class="big">The title of this map is The Block Around the Lot. The little pictures and their words are the legend. The compass is the directional indicator. Printed in the corner are the scale, one inch stands for one block, and the date, this spring.</p>
     <p class="big">Land in California gets used in three different ways. In a <b>city</b> the buildings are tall and close together and many people live on one block. In the <b>suburbs</b> outside a city there are houses with yards and wide streets. Out in the <b>country</b> there are farms and ranches, with miles between the houses.</p>`,qs:["Give the exact square the corner lot is in, using its letter and number.","What is directly north of the corner lot?","This map carries five map elements. Name the title of this map, and name two of the other four elements and say what each one tells you.","Name the three ways land gets used in California, and say which one this map shows."],key:["B2","the park, in square A2","The title is The Block Around the Lot. Any two of: the legend, which says what the symbols mean; the directional indicator or compass, which shows which way is north; the scale, which says one inch stands for one block; the date, which says when the map was made. (HSS-2.2)","A city, the suburbs, and the country. Accept urban, suburban and rural. This map shows a city block, because the buildings are close together with a library, a bakery and a bus stop all on one block. (HSS-2.2)"]}]},{id:31,title:"Rules, Money and the Plant Sale",short:"Rules and Money",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling what governments do here, and how another country chooses a leader differently",html:()=>`<p class="big">The city owns this corner lot and lets the garden club use it. The club had to ask the city council first.</p>
     <p class="big">The club’s seeds came from three different countries. Countries deal with each other all the time. They <b>trade</b>. That means buying and selling goods. Things like seeds and tools. They have <b>cultural contact</b>. That means their people visit. They share food and music. They learn each other’s languages. They sign <b>treaties</b>, which are written agreements. All of that is work to solve problems without fighting.</p>
     <div class="figure">${ic("flag",80)}${ic("books",80)}</div>`,qs:["The club wanted to use land the city owns. Who had to say yes? A city council the people elect, or the person who lives closest?","Name one thing a city government does for the people who live there.","The club’s seeds came from three countries. Name two ways countries deal with each other to solve problems, and say which of those two a bag of seeds is an example of."],key:["a city council the people elect","Any real answer: runs the parks, collects the rubbish, fixes the roads, runs the buses, pays for the fire department and the library.","Any two of: trade, cultural contact, signing a treaty. A bag of seeds crossing a border is trade. Both parts are what is being checked. (HSS-2.3)"]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the price list. Answer out loud.",desc:"telling goods from services, telling a want from a need, and spending a set amount",html:()=>`<p class="big">The club's spring plant sale at the gate.</p>
     <table class="bigTable"><tr><th>What is on offer</th><th>Price</th></tr>
     <tr><td>a tomato seedling</td><td>45 cents</td></tr>
     <tr><td>a bunch of radishes</td><td>30 cents</td></tr>
     <tr><td>a painted plant label</td><td>10 cents</td></tr>
     <tr><td>someone to carry your tray home for you</td><td>25 cents</td></tr></table>
     <div class="figure">${ic("tulip",72)}${ic("carrot",72)}</div>`,qs:["Three things on this list are goods and one is a service. Which one is the service, and how do you know?","Food is something people need. A painted label is something people just want. Which thing on this list is a need, and which is only a want?","You have 55 cents. Name two things you could buy with it, and say what you give up."],key:["Someone carrying your tray home. It is work somebody does for you, not a thing you keep.","The bunch of radishes is food, so it is a need. The painted label is only a want. The seedling can be argued either way: it becomes food later, so accept it as a need if the student says so.","Any pair at 55 cents or less: radishes and a label is 40 cents, radishes and the carrying is 55 cents, a seedling and a label is 55 cents. The giving up is the part to listen for."]}]},{id:32,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about him. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Sitting Bull was a leader. He led the Lakota people. They lived on the northern plains. He was known for standing calmly. He stood by what he believed. People listened to him because of it. Others wanted the Lakota to give up land. They had always lived and hunted there. He said no. He kept saying it for years. He worked to hold his people together. He worked to keep their language. He worked to keep their way of living. He also looked after children. They had lost their families. Adopted some of them himself. The Lakota still tell about him today.</p>
     <div class="figure">${ic("mountain",80)}${ic("star",80)}</div>`,qs:["What did Sitting Bull keep saying no to, for years?","Which word fits him best from what you read: steadfast, careless, or selfish? Say why.","Name one way what he did made a difference to other people."],key:["Giving up the land where the Lakota had always lived and hunted.","steadfast. Accept strong or loyal with the same reasons. Any reason taken from the text: he stood calmly by what he believed and kept saying it for years, he held his people together.","Any answer from the text: he worked to hold his people together, he helped keep their language and way of living, he looked after children who had lost their families, the Lakota still tell about him."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Long Garden Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each long word out loud.",html:()=>`<div style="text-align:center">${["germinate","invisible","temperature"].map(w=>`<p class="huge" style="font-size:clamp(2.4rem,8vw,4.4rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["germinate (ger-mi-nate, the r-controlled first part)","invisible (in-vis-i-ble)","temperature (tem-per-a-ture)"]},3:{id:"L3",title:"Level Up: Show Me the Words",std:["RL.3.1"],needs:["RL.2.1"],n:2,dir:"Answer out loud. Then read the words from the story that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${CORNER_LOT}</p><ol class="qlist"><li>How do you know the lot had been left alone for a whole year? Read the part of the story that shows it.</li><li>How do you know a lot of people work on it, not just one or two? Read the part that shows it.</li></ol>`,key:["Says the beds were full of old growth, and reads the line about pulling last year's dry stalks out of the beds, or the line about a field of weeds.","Reads the line that the whole block meets at the lot, or the lines about somebody bringing a wheelbarrow and somebody else bringing a crate."]},6:{id:"L6",title:"Level Up: Prove It",std:["RI.3.1"],needs:["RI.2.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${WHY_RAIN}</p><ol class="qlist"><li>How do you know a cloud is not solid? Read the part of the text that shows it.</li><li>How do you know the water in today's rain is not new water? Read the part that shows your answer.</li></ol>`,key:["Says a cloud is really a crowd of tiny floating drops, and reads the line that millions of those drops floating together are what you see as a cloud.","Reads the last line, that the same water has been going around like this for a very long time."]},7:{id:"L7",title:"Level Up: Grown-Up Grammar",std:["L.3.1"],needs:["L.2.1"],n:2,dir:"Say each answer out loud.",html:()=>`<ol class="qlist"><li>One sprout is tall. After a week of rain the whole row is ____ than it was.</li><li>Join these two sentences with the word <b>although</b>: The soil was still cold. We planted anyway.</li></ol>`,key:["taller (the comparative form)","Although the soil was still cold, we planted anyway. (Or: We planted anyway although the soil was still cold.)"]},10:{id:"L10",title:"Level Up: Two to a Square",std:["3.MD.B.3"],needs:["2.MD.D.10"],n:3,dir:"Look at the new graph. The numbers up the side now go up by 2 instead of by 1. Answer out loud.",html:()=>`<div class="figure">${F.barGraph({title:"Sprouts in each row",cats:["Beans","Peas","Corn","Kale"],vals:[16,10,18,12],max:20,step:2})}</div><ol class="qlist"><li>How many sprouts are up in the bean row?</li><li>How many more corn sprouts than pea sprouts?</li><li>If the carrot row had 14 sprouts, how high would its bar reach?</li></ol>`,key:["16 sprouts. The bar stops on the line marked 16.","8 more (18 - 10 = 8)","Up to the 14 line, which is 7 steps up a scale that counts by 2"]}};const PASSAGE_STD=["RL.2.1","RL.2.2","RI.2.1","RL.3.1","RI.3.1","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let chartOn={},pvVal=["",""],blk=[0,0,0];function chartHtml(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${chartOn[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function matSvg(h,t,o){return F.blocks(h,t,o)}function blkHtml(){const b=(k,t)=>`<button class="chip" data-b="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]+blk[2]?matSvg(blk[0],blk[1],blk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} hundreds, ${blk[1]} tens, and ${blk[2]} ones on the mat.</p>`}function blkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")blk=[0,0,0];else if(k==="to"){if(blk[2]>=10&&blk[1]<19){blk[2]-=10;blk[1]++}}else if(k==="th"){if(blk[1]>=10&&blk[0]<9){blk[1]-=10;blk[0]++}}else if(k==="bt"){if(blk[1]>=1&&blk[2]<=9){blk[1]--;blk[2]+=10}}else if(k==="bh"){if(blk[0]>=1&&blk[1]<=9){blk[0]--;blk[1]+=10}}else blk[i]=Math.max(0,Math.min(MAX[i],blk[i]+(k[1]==="+"?1:-1)))}function coinHtml(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;align-items:flex-end">${[["Q","25¢"],["D","10¢"],["N","5¢"],["P","1¢"]].map(([k,v])=>`<span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.coin(k)}<b style="font-size:1.1rem">${v}</b></span>`).join("")}</div><div style="display:flex;gap:18px;flex-wrap:wrap;justify-content:center;align-items:flex-end;margin-top:12px"><span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.bill(1)}<b style="font-size:1.1rem">$1 = 100¢</b></span><span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.bill(5)}<b style="font-size:1.1rem">$5 = 500¢</b></span></div><p class="small" style="margin:8px 0 0">This chart gives the value of each coin. The student still does the adding and still writes the cent sign.</p>`}const STARTERS={"W.2.1":["I think ____ is the better job.","One reason is ____.","Also, ____.","So that is the job I would pick."],"W.2.2":["This is about ____.","A sprout is ____.","First, ____.","Then, ____.","So that is how ____."],"W.2.3":["One day, ____.","First, ____.","Then, ____.","After that, ____.","In the end, ____."],"W.2.8":["The log says ____.","On Monday the crew counted ____.","The most sprouts came up on ____.","I remember ____."]};function sentHtml(st){const k=st&&st.parts&&st.parts[0]&&st.parts[0].std&&st.parts[0].std[0]||"W.2.3";return`<ul class="starters">${(STARTERS[k]||STARTERS["W.2.3"]).map(x=>`<li>${x}</li>`).join("")}</ul>`}let tpsNlStart="",tpsNlHops=[],tpsNlShown={};function tpsNlSvg(){if(tpsNlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+tpsNlStart];tpsNlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;tpsNlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+tpsNlStart||tpsNlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+tpsNlStart?"":`data-tv="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function tpsNlHtml(){const j=d=>`<button class="chip" data-tj="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="tpsNlStart" value="${tpsNlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-tj="u">Undo</button><button class="chip" data-tj="x">Clear</button></div><div class="tool-scroll" id="tpsNlBox" style="text-align:center">${tpsNlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function tpsNlBind(b,r){const box=()=>b.querySelectorAll("[data-tv]").forEach(g=>g.onclick=()=>{tpsNlShown[g.dataset.tv]=!tpsNlShown[g.dataset.tv];r()});const inp=b.querySelector("#tpsNlStart");inp.oninput=()=>{tpsNlStart=inp.value.replace(/[^0-9]/g,"");tpsNlShown={};b.querySelector("#tpsNlBox").innerHTML=tpsNlSvg();box()};b.querySelectorAll("[data-tj]").forEach(x=>x.onclick=()=>{const k=x.dataset.tj;if(k==="x"){tpsNlHops=[];tpsNlShown={}}else if(k==="u")tpsNlHops.pop();else if(tpsNlStart!==""&&tpsNlHops.length<10)tpsNlHops.push(+k);r()});box()}function tpsClockHtml(){return`<div style="text-align:center;margin:8px 0"><img alt="A clock face. The short red hour hand points to the 10. The long blue minute hand points to the 12. Big numbers 1 to 12 are the hours. Small labels around the edge count minutes by fives, from :00 to :55." src="data:image/webp;base64,${window.TP_IMG1.wp.clocklab}" style="width:340px;max-width:100%;height:auto"></div>`+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return `<div style="text-align:center"><img alt="An inch ruler from 0 to 6 with a pencil lined up at 0. The tip of the pencil is at 5 inches." src="data:image/webp;base64,${window.TP_IMG1.wp3.inchruler}" style="width:640px;max-width:100%;height:auto"></div>`+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:chartHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{chartOn[x.dataset.n]=!chartOn[x.dataset.n];r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{blkDo(x.dataset.b);r()})},coins:{name:"Coin values",std:["2.MD.C.8"],html:coinHtml},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:tpsNlHtml,bind:tpsNlBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"chart",std:["2.OA.A.1"],msg:"With the 120 chart the student can count on or back square by square. Note it if the answer came from counting by ones."},{t:"chart",std:["2.OA.C.3"],msg:"Skip counting by 2s down the chart hands the student the even numbers. Note whether the odd and even answers came from the chart or from pairing the pictures up."},{t:"pv",std:["2.NBT.B.7"],msg:"The place value chart lines the digits up by place, which is most of the work in a written method. Note it."},{t:"blocks",std:["2.NBT.B.7","2.OA.A.1"],msg:"If you built the numbers with blocks for the student, the item shows they can trade with a model, not that they can use a written method on their own."},{t:"coins",std:["2.MD.C.8"],msg:"The coin values chart supplies what each coin is worth, so the money items done with it show adding and the cent sign, not knowing the coins. Count them as supported, not independent."},{t:"sent",msg:"Sentence starters supply the opening, the linking and time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"chart",std:["2.NBT.A.2"],msg:"The 120 chart shows the counting order and the columns of tens, so a skip count read off it is supported, not said from memory. It does not reach past 120 anyway, so the count on past 600 and the 100s count are unsupported either way."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens and ones for the student, which is most of what this stop asks. Note it."},{t:"blocks",std:["2.NBT.A.1","2.NBT.A.3"],msg:"If you built or rebuilt the mat for the student, the item shows reading a model you made, not reading the places alone. Note it."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
